use super::*;
fn schema()->Value{serde_json::from_str(include_str!("../../🏡️zone/🧊️change-volume/🧬️schema/🔣️.json")).unwrap()}
fn input()->DeriveInput{syn::parse_str("pub struct ChangeZoneVolume{pub id:crate::model::EntityId,pub new_volume_m3:f64}").unwrap()}
fn compile_schema(schema:&Value)->syn::Result<Tokens>{compile(&input(),schema,&syn::parse_str("::protocol").unwrap(),&syn::parse_str("crate::snapshot").unwrap(),&syn::parse_str("crate::diff").unwrap())}
#[test]
fn authored_scalar_recipe_compiles_a_typed_original_leaf_and_exact_key_field(){let output=compile_schema(&schema()).unwrap();let file:syn::File=syn::parse2(output.clone()).unwrap();assert_eq!(file.items.len(),6);let source=output.to_string();for symbol in["ScalarLeafPreparation","RetainedMutationLeaf","ScalarRowPath","StateZone","ModelGeometryState","new_volume_m3","volume_m3","is_finite","ChangedZoneVolume"]{assert!(source.contains(symbol),"native authored binding missing {symbol}");}}
#[test]
fn authored_native_recipe_refuses_missing_unsupported_or_inconsistent_sources(){let original=schema();let mut missing=original.clone();missing.as_object_mut().unwrap().remove("x-semio-energy-operation");assert!(compile_schema(&missing).is_err());let mut unsupported=original.clone();unsupported["x-semio-energy-operation"]["category"]="cold-copy".into();assert!(compile_schema(&unsupported).is_err());let mut field=original.clone();field["x-semio-energy-operation"]["input"]="invented_field".into();assert!(compile_schema(&field).is_err());let mut ty=original.clone();ty["properties"]["newVolumeM3"]["type"]="boolean".into();assert!(compile_schema(&ty).is_err());let mut label=original.clone();label["x-semio-energy-operation"]["labels"].as_object_mut().unwrap().remove("de");assert!(compile_schema(&label).is_err());let mut path=original.clone();path["x-semio-energy-operation"]["row"]="NotAType; panic!()".into();assert!(compile_schema(&path).is_err());}
#[test]
fn every_proven_zone_scalar_recipe_matches_its_actual_authored_payload_fields(){for(source,schema)in[(include_str!("../../🏡️zone/🧊️change-volume/🦀️.rs"),include_str!("../../🏡️zone/🧊️change-volume/🧬️schema/🔣️.json")),(include_str!("../../🏡️zone/✖️change-multiplier/🦀️.rs"),include_str!("../../🏡️zone/✖️change-multiplier/🧬️schema/🔣️.json")),(include_str!("../../🏡️zone/🌬️change-conditioned/🦀️.rs"),include_str!("../../🏡️zone/🌬️change-conditioned/🧬️schema/🔣️.json")),(include_str!("../../🏡️zone/📐️change-floor-area-participation/🦀️.rs"),include_str!("../../🏡️zone/📐️change-floor-area-participation/🧬️schema/🔣️.json"))]{let schema:Value=serde_json::from_str(schema).unwrap();let parsed=syn::parse_file(source).unwrap();let input=parsed.items.into_iter().find_map(|item|if let syn::Item::Struct(item)=item{Some(DeriveInput{attrs:item.attrs,vis:item.vis,ident:item.ident,generics:item.generics,data:syn::Data::Struct(syn::DataStruct{struct_token:item.struct_token,fields:item.fields,semi_token:item.semi_token})})}else{None}).unwrap();let output=compile(&input,&schema,&syn::parse_str("::protocol").unwrap(),&syn::parse_str("crate::snapshot").unwrap(),&syn::parse_str("crate::diff").unwrap()).unwrap();syn::parse2::<syn::File>(output).unwrap();}}

#[test]
fn all_authored_scalar_recipes_match_real_payloads_and_compile_typed_original_paths(){
 let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../..");let mut count=0;let mut collections=std::collections::BTreeSet::new();
 for group in std::fs::read_dir(&root).unwrap(){let group=group.unwrap().path();if !group.is_dir(){continue;}for leaf in std::fs::read_dir(group).unwrap(){let leaf=leaf.unwrap().path();let schema_path=leaf.join("🧬️schema/🔣️.json");if !schema_path.is_file(){continue;}let schema:Value=serde_json::from_str(&std::fs::read_to_string(schema_path).unwrap()).unwrap();let Some(recipe)=schema.get("x-semio-energy-operation")else{continue;};if !["scalar-row","enum-row","reference-row","name-row","scalar-field","owned-row"].iter().any(|c|recipe["category"]==*c){continue;}let source=std::fs::read_to_string(leaf.join("🦀️.rs")).unwrap();let parsed=syn::parse_file(&source).unwrap();let input=parsed.items.into_iter().find_map(|item|if let syn::Item::Struct(item)=item{Some(DeriveInput{attrs:item.attrs,vis:item.vis,ident:item.ident,generics:item.generics,data:syn::Data::Struct(syn::DataStruct{struct_token:item.struct_token,fields:item.fields,semi_token:item.semi_token})})}else{None}).unwrap();let output=compile(&input,&schema,&syn::parse_str("::protocol").unwrap(),&syn::parse_str("crate::snapshot").unwrap(),&syn::parse_str("crate::diff").unwrap()).unwrap_or_else(|e|panic!("{}: {e}",leaf.display()));syn::parse2::<syn::File>(output).unwrap();if let Some(collection)=recipe.get("collection").and_then(Value::as_str){collections.insert(collection.to_owned());}count+=1;}}
 assert_eq!(count,185);assert!(collections.len()>=25);
}

#[test]
fn authored_name_recipes_preserve_original_string_storage_and_uniqueness_policy(){let schema:Value=serde_json::from_str(include_str!("../../🏡️zone/🏠️rename/🧬️schema/🔣️.json")).unwrap();let input:DeriveInput=syn::parse_str("pub struct RenameZone{pub id:crate::model::EntityId,pub new_name:String}").unwrap();let compile=|schema:&Value|super::compile(&input,schema,&syn::parse_str("::protocol").unwrap(),&syn::parse_str("crate::snapshot").unwrap(),&syn::parse_str("crate::diff").unwrap());let output=compile(&schema).unwrap();syn::parse2::<syn::File>(output.clone()).unwrap();let source=output.to_string();for symbol in["TextRowPath","TextLeafSpec","TextLeafPreparation","SealedShared < String >","UNIQUE","DUPLICATE"]{assert!(source.contains(symbol),"name schema binding missing {symbol}");}let mut missing=schema.clone();missing["x-semio-energy-operation"].as_object_mut().unwrap().remove("unique");assert!(compile(&missing).is_err());let mut unbounded=schema.clone();unbounded["properties"]["newName"].as_object_mut().unwrap().remove("minLength");assert!(compile(&unbounded).is_err());}

#[test]
fn all_authored_creation_field_recipes_compile_real_original_typed_row_births(){let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../..");let mut count=0;for group in std::fs::read_dir(root).unwrap(){let group=group.unwrap().path();if !group.is_dir(){continue;}for leaf in std::fs::read_dir(group).unwrap(){let leaf=leaf.unwrap().path();let path=leaf.join("🧬️schema/🔣️.json");if !path.is_file(){continue;}let schema:Value=serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();if schema.get("x-semio-energy-row-birth").is_none(){continue;}let parsed=syn::parse_file(&std::fs::read_to_string(leaf.join("🦀️.rs")).unwrap()).unwrap();let item=parsed.items.into_iter().find_map(|item|if let syn::Item::Struct(item)=item{Some(item)}else{None}).unwrap();let input=DeriveInput{attrs:item.attrs,vis:item.vis,ident:item.ident,generics:item.generics,data:syn::Data::Struct(syn::DataStruct{struct_token:item.struct_token,fields:item.fields,semi_token:item.semi_token})};let output=row_birth::compile(&input,&schema).unwrap_or_else(|e|panic!("{}: {e}",leaf.display()));syn::parse2::<syn::File>(output.clone()).unwrap();assert!(output.to_string().contains("RowBirthSpec"));let mut invalid=schema.clone();invalid["x-semio-energy-row-birth"]["fields"][0]["input"]="invented_source".into();assert!(row_birth::compile(&input,&invalid).is_err());count+=1;}}assert_eq!(count,38);}

