fn authored_delete_recipe_preserves_actual_row_inverse_and_explicit_restriction(){let schema:Value=serde_json::from_str(include_str!("../../🔥️solar-thermal/🌆️delete/🧬️schema/🔣️.json")).unwrap();let input:DeriveInput=syn::parse_str("pub struct DeleteSolarThermalSystem{pub id:crate::model::EntityId}").unwrap();let compile=|schema:&Value|super::compile(&input,schema,&syn::parse_str("::protocol").unwrap(),&syn::parse_str("crate::snapshot").unwrap(),&syn::parse_str("crate::diff").unwrap());let output=compile(&schema).unwrap();syn::parse2::<syn::File>(output.clone()).unwrap();for symbol in["DeleteRowPreparation","RowRecreation","CreateSolarThermalSystem","NoRowReferences","RowLeafPreparation"]{assert!(output.to_string().contains(symbol));}let mut unsupported=schema.clone();unsupported["x-semio-energy-operation"]["restriction"]="ignore-references".into();assert!(compile(&unsupported).is_err());}
