fn authored_zone_delete_retains_all_seventeen_actual_restrictions_and_the_optional_original_network(){let schema:Value=serde_json::from_str(include_str!("../../🏡️zone/🏚️delete/🧬️schema/🔣️.json")).unwrap();let input:DeriveInput=syn::parse_str("pub struct DeleteZone{pub id:crate::model::EntityId}").unwrap();let compile=|schema:&Value|super::compile(&input,schema,&syn::parse_str("::protocol").unwrap(),&syn::parse_str("crate::snapshot").unwrap(),&syn::parse_str("crate::diff").unwrap());let output=compile(&schema).unwrap();syn::parse2::<syn::File>(output.clone()).unwrap();let tokens=output.to_string();assert_eq!(tokens.matches("AllRowReferences").count(),16);assert!(tokens.contains("RootReferenceGuard"));assert!(tokens.contains("zone_node_ids"));let mut unsupported=schema.clone();unsupported["x-semio-energy-operation"]["restriction"]["sources"]=serde_json::json!([]);assert!(compile(&unsupported).is_err());}
